    for(auto id:actors){
        if(!alive(id,NativeKind::Unit))continue;auto u=units_.at(id);if(!u->cast || u->paused || u->mirrorImage)continue;auto cast=*u->cast;
        auto valid=[&]{return alive(id,NativeKind::Unit) && !u->paused && !u->stunned() && !u->removing && number(u->life)>0 && u->cast && u->cast->ticket==cast.ticket;};
        if(u->removing || u->stunned() || u->hidden() || number(u->life)<=0 || (!u->abilities.contains(cast.spell.ability) || u->abilities.at(cast.spell.ability)<=0) || u->owner!=cast.owner){cancelCast(*u);continue;}
        if(cast.phase==CastOrder::Phase::Backswing){u->cast->remaining-=delta;if(u->cast->remaining<=0)finishCast(id,cast.ticket);continue;}
        if(cast.spell.targeting==SpellTargeting::Unit){if(!spellWidgetTarget(*u,cast.target,cast.spell,true)){cancelCast(*u);continue;}u->cast->point=*spellWidgetPoint(cast.target);}else if(cast.spell.targeting==SpellTargeting::None)u->cast->point={u->x,u->y};
        if(cast.phase==CastOrder::Phase::Channel){channelTick(id,delta);continue;}
        cast.point=u->cast->point;float range=cast.spell.range+u->collision+(cast.spell.targeting==SpellTargeting::Unit?spellTargetCollision(cast.target):0);float targetDistance=cast.spell.unlimitedRange || cast.spell.targeting==SpellTargeting::None?0:distance(*u,cast.point);
        if(cast.phase==CastOrder::Phase::Approach){
            if(targetDistance>range){if(u->rooted() || u->building || number(u->moveSpeed)<=0){cancelCast(*u);continue;}if(simulationTime_>=cast.repath){if(!chase(*u,cast.point,std::max(0.f,range-8))){cancelCast(*u);continue;}u->cast->repath=simulationTime_+.25;}continue;}
            if(!spellRequirements(u->owner,cast.spell) || number(u->mana)<cast.spell.mana || spellCooldown(id,cast.spell.ability)>0 || !spellPoint(*u,cast.spell,cast.point)){cancelCast(*u);continue;}
            u->route.clear();u->waypoint=0;if(targetDistance>.001f)u->facing=real(std::fmod(std::atan2(number(cast.point.y)-number(u->y),number(cast.point.x)-number(u->x))*180.f/3.14159265359f+360.f,360.f));u->animation=cast.spell.animation;u->animationIndex.reset();u->animationQueue.clear();u->animationTime=0;u->cast->started=true;u->cast->phase=CastOrder::Phase::Windup;u->cast->remaining=std::max(0.f,definitions().number(u->type,"UnitWeapons","castpt"));cast=*u->cast;spellEvent(id,cast,0);if(!valid())continue;spellEvent(id,cast,1);if(!valid())continue;
        }else u->cast->remaining-=delta;
        if(!valid() || u->cast->remaining>0)continue;
        if(cast.spell.targeting==SpellTargeting::Unit){if(!spellWidgetTarget(*u,cast.target,cast.spell,false)){cancelCast(*u);continue;}cast.point=*spellWidgetPoint(cast.target);u->cast->point=cast.point;targetDistance=cast.spell.unlimitedRange?0:distance(*u,cast.point);}
        if(!spellRequirements(u->owner,cast.spell) || number(u->mana)<cast.spell.mana || targetDistance>range+gameplayNumber("SpellCastRangeBuffer",300) || !spellPoint(*u,cast.spell,cast.point)){cancelCast(*u);continue;}
        u->mana=real(number(u->mana)-cast.spell.mana);u->spellCooldowns[cast.spell.ability]=simulationTime_+cast.spell.cooldown;u->cast->phase=CastOrder::Phase::Backswing;u->cast->remaining=std::max(0.f,definitions().number(u->type,"UnitWeapons","castbsw"));auto owner=u->owner;breakInvisibility(*u);spellEvent(id,cast,2);if(alive(id,NativeKind::Unit) && u->cast && u->cast->ticket==cast.ticket && u->owner==owner)releaseSpell(id,cast,owner);
    }
